/*
 * Shown when an unknown error occurs (ErrorBoundaries, generic exception caught, etc)
 */

import {Banner} from '@primer/react'

function PrimaryAction() {
  return <Banner.PrimaryAction onClick={() => window.location.reload()}>Refresh</Banner.PrimaryAction>
}

export function UnknownExceptionBanner() {
  const description =
    'An unknown error occurred while attempting to display this message. Try refreshing the page to reconnect.'
  const title = 'Message cannot be displayed'
  const variant = 'critical'

  return (
    <Banner
      className="rounded-0"
      style={{outline: 'none'}}
      description={description}
      hideTitle
      title={title}
      variant={variant}
      primaryAction={<PrimaryAction />}
    />
  )
}
