import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useDebounce} from '@github-ui/use-debounce'
import {useStableCallback} from '@github-ui/use-stable-callback'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {createContext, use, useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useAnalytics} from '../telemetry/use-analytics'
import type {GitFileStatuses} from '../types/file-syncer-v2-types'
import type {Iteration, WorkbenchRoutePayload} from '../types/workbench-types'
import {commitDataToIteration} from '../utilities/commit-data-to-iteration'
import {withRetries} from '../utilities/with-retries'
import {useFileSyncerContext} from './FileSyncerContext'
import {useAgentStatus} from './WorkbenchStoreContext'

export type IterationHistoryContext = {
  setCurrentRefinement: (refinementId: number | undefined, saveToLocalStorage?: boolean) => void
  previousRefinements: Iteration[]
  setPreviousRefinements: (value: Iteration[] | ((prev: Iteration[]) => Iteration[])) => void
  currentRefinementId: number | undefined
  isNavigatingHistory: boolean
  setIsNavigatingHistory: (value: boolean) => void
  updateUserEditStatus: (message: string) => Promise<void>
  updateIterationsFromServer: () => Promise<void>
  currentRefinementSha: string | undefined
  previousRefinementSha: string | null
  isInitialIteration: boolean
  refreshGitHistory: () => Promise<void>
  notifyRehydrateCompleted: () => void
  gitHistoryRestored: boolean
}

type PollingStateData = {
  previousRefinements: Iteration[]
  currentRefinementId: number | undefined
  currentRefinementSha?: string
  fileSyncerStarted: boolean
  isAgentBusy: boolean
}

export const UNCOMMITTED_HASH = 'UNCOMMITTED'

export function IterationHistoryProvider({children}: {children: React.ReactNode}) {
  const {workbench} = useRoutePayload<WorkbenchRoutePayload>()
  const iterationsInDbRef = useRef<Iteration[]>(workbench.previousRefinements || [])
  const sendEvent = useAnalytics()

  const [previousRefinements, setPreviousRefinements] = useState<Iteration[]>(workbench.previousRefinements || [])
  const initialRefinmentId = workbench.currentRefinementId ? workbench.currentRefinementId : undefined
  const [currentRefinementId, setCurrentRefinementId] = useState<number | undefined>(initialRefinmentId)
  const [currentRefinementSha, setCurrentRefinementSha] = useState<string | undefined>()
  const [isNavigatingHistory, setIsNavigatingHistory] = useState(false)
  const [gitHistoryRestored, setGitHistoryRestored] = useState(false)
  const shaFilesMapRef = useRef<Map<string, GitFileStatuses>>(new Map())
  const [unCommittedFilesHash, setUnCommittedFilesHash] = useState<string>('')
  const {
    getFileSyncerV2,
    fileSyncerStarted,
    syncerMode,
    forceContentRefresh,
    forceFileTreeRefresh,
    lastEditStateStamp,
  } = useFileSyncerContext()
  const {isAgentBusy} = useAgentStatus()
  const refreshHistoryRef = useRef<Promise<void> | null>(null)
  // Using a ref here since we're scheduling an interval that needs to access the latest state
  // without causing re-renders.
  const pollingStateRef = useRef<PollingStateData>({
    previousRefinements,
    currentRefinementId,
    currentRefinementSha,
    fileSyncerStarted,
    isAgentBusy,
  })

  const setCurrentRefinement = useStableCallback((refinementId: number | undefined) => {
    setCurrentRefinementId(refinementId)
    if (refinementId === undefined) {
      setCurrentRefinementSha(undefined)
    }

    const refinement = previousRefinements.find(ref => ref.id === refinementId)
    if (refinement) {
      setCurrentRefinementSha(refinement.sha)
    }
  })

  const getUncommitedIteration = useCallback(
    async (headSha: string | undefined): Promise<Iteration | undefined> => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer || !fileSyncerStarted) {
        return undefined
      }
      const files = await fileSyncer.getGitStatus()
      const filesHash = JSON.stringify(files)
      if (unCommittedFilesHash !== filesHash) {
        setUnCommittedFilesHash(filesHash)
      }

      if (Object.keys(files).length > 0) {
        const tempIteration = {
          iteration_type: 'user',
          files,
          parentSha: headSha,
          sha: UNCOMMITTED_HASH,
        } satisfies Iteration
        return tempIteration
      }

      return undefined
    },
    [getFileSyncerV2, fileSyncerStarted, unCommittedFilesHash],
  )

  const updateRefinementsFromCommits = useCallback(
    async (iterations: Iteration[], headSha: string) => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer || !fileSyncerStarted) {
        return
      }

      const tempIteration = await getUncommitedIteration(headSha)
      if (tempIteration) {
        setPreviousRefinements([...iterations, tempIteration])
        setCurrentRefinementSha(tempIteration.sha)
      } else {
        const files = await fileSyncer.getChangedFilesFiltered(headSha)
        if (Object.keys(files).length > 0) {
          shaFilesMapRef.current.set(headSha, files)
          const headIterationIndex = iterations.findLastIndex(iteration => iteration.sha === headSha)
          if (headIterationIndex !== -1) {
            const headIteration = iterations[headIterationIndex]
            if (headIteration) {
              headIteration.files = files
            }
          }
          setPreviousRefinements([...iterations])
        }
        setCurrentRefinementSha(headSha)
      }
    },
    [fileSyncerStarted, getFileSyncerV2, getUncommitedIteration],
  )

  const fetchIterationHistoryFromGitV2 = useCallback(async () => {
    const fileSyncer = getFileSyncerV2()
    const commitHistoryAll = await withRetries(() => fileSyncer?.getCommitHistory(), {
      retries: 3,
      retryDelayMs: 500,
      exponentialBackoffFactor: 1.5,
    })
    const headSha = commitHistoryAll?.find(commit => commit.isHead)?.sha

    // Filter out commits that don't have a parentSha, essentially ignoring the initial commit since it won't have a parent.
    const commitHistory = commitHistoryAll?.filter(commit => commit.parentSha)

    if (!headSha) {
      throw new Error('Unable to determine head SHA from commit history')
    }

    const iterations: Iteration[] =
      commitHistory
        ?.map(commit =>
          commitDataToIteration(commit, {
            iterationsInDb: iterationsInDbRef.current,
            localStateRefinements: pollingStateRef.current.previousRefinements,
          }),
        )
        .reverse() || []

    const currentRefinement = iterations.find(iteration => iteration.sha === headSha)
    return {iterations, currentRefinement}
  }, [getFileSyncerV2])

  const refreshGitHistory = useCallback(async () => {
    // If there's already a request in progress, return the existing one
    if (refreshHistoryRef.current) {
      return refreshHistoryRef.current
    }

    // Create and execute a new async function for this request
    const refreshHistory = (async () => {
      try {
        const result = await fetchIterationHistoryFromGitV2()
        const headSha = result.currentRefinement?.sha || ''
        const files = shaFilesMapRef.current.get(headSha)
        if (files) {
          const iteration = result.iterations.find(x => x.sha === headSha)
          if (iteration) {
            iteration.files = files
          }
        }

        setPreviousRefinements(result.iterations)
        await updateRefinementsFromCommits(result.iterations, headSha)

        sendEvent('iteration_history.refresh_git_history_success', {
          iteration_count: result.iterations.length ?? 0,
        })
      } catch (error) {
        sendEvent('iteration_history.refresh_git_history_error', {
          error: error instanceof Error ? error.message : String(error),
        })
      } finally {
        // Clear the promise ref when done
        refreshHistoryRef.current = null
      }
    })()

    refreshHistoryRef.current = refreshHistory

    return refreshHistory
    // remove sendEvent from deps
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fetchIterationHistoryFromGitV2, updateRefinementsFromCommits])

  const notifyRehydrateCompleted = useCallback(() => {
    setGitHistoryRestored(true)
  }, [])

  useEffect(() => {
    if (!fileSyncerStarted || syncerMode !== 'codespace') return
    if (!gitHistoryRestored) return
    if (isAgentBusy) return

    refreshGitHistory()
  }, [fileSyncerStarted, isAgentBusy, refreshGitHistory, syncerMode, gitHistoryRestored])

  const updateUncommittedIteration = useCallback(async () => {
    try {
      const uncommittedIterationIdx = previousRefinements.findIndex(
        ref => ref.iteration_type === 'user' && ref.sha === UNCOMMITTED_HASH,
      )

      const headSha =
        uncommittedIterationIdx === -1
          ? currentRefinementSha
          : previousRefinements[uncommittedIterationIdx]?.parentSha || ''

      const uncommittedIteration = await getUncommitedIteration(headSha)
      if (!uncommittedIteration) {
        if (uncommittedIterationIdx !== -1) {
          // If there are no uncommitted changes, but we had an in-progress user edit, remove it.
          setPreviousRefinements(prev => prev.filter((_, idx) => idx !== uncommittedIterationIdx))
          setCurrentRefinementSha(headSha)
        }
        return
      }

      setPreviousRefinements(prev => {
        if (uncommittedIterationIdx === -1) {
          return [...prev, uncommittedIteration]
        } else {
          const updated = [...prev]
          updated[uncommittedIterationIdx] = uncommittedIteration
          return updated
        }
      })
      setCurrentRefinementSha(uncommittedIteration.sha)
    } catch {
      // Any error will be logged by the underlying file syncer
    }
  }, [previousRefinements, currentRefinementSha, getUncommitedIteration])

  const debouncedUpdateUncommittedIteration = useDebounce(updateUncommittedIteration, 300, {
    leading: false,
    trailing: true,
  })

  useEffect(() => {
    if (!fileSyncerStarted || syncerMode !== 'codespace') return
    if (!gitHistoryRestored) return
    if (isAgentBusy) return

    debouncedUpdateUncommittedIteration()

    // lastEditStateStamp is included to ensure we refresh git status after user edits
  }, [
    fileSyncerStarted,
    isAgentBusy,
    syncerMode,
    gitHistoryRestored,
    lastEditStateStamp,
    debouncedUpdateUncommittedIteration,
  ])

  pollingStateRef.current = {
    previousRefinements,
    currentRefinementId,
    fileSyncerStarted,
    isAgentBusy,
  }

  const updateUserEditStatus = useCallback(
    async (message: string) => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer || !fileSyncerStarted) {
        return
      }
      const statusResults = await fileSyncer.getGitStatus()
      const currentRefinement = previousRefinements.find(ref => ref.id === currentRefinementId)

      if (!currentRefinement || currentRefinement.iteration_type !== 'user' || currentRefinement.sha) {
        const updatedRefinement: Iteration = {
          prompt: message,
          iteration_type: 'user',
          parentId: currentRefinementId || undefined,
          files: statusResults,
        }
        setPreviousRefinements(prev => [...prev, updatedRefinement])
        setCurrentRefinement(updatedRefinement.id)
      } else {
        // If there are no file changes, but we had an in-progress user edit, remove it.
        if (Object.keys(statusResults).length === 0) {
          setPreviousRefinements(prev => prev.filter(ref => ref.id !== currentRefinementId))
          setCurrentRefinement(currentRefinement.parentId || undefined)
          return
        }

        // If the user is editing an existing user iteration, we need to update the files
        const updatedRefinement = {
          ...currentRefinement,
          files: statusResults,
        }
        setPreviousRefinements(prev => {
          const newPreviousRefinements = [...prev]
          const currentRefinementIndex = prev.findIndex(ref => ref.id === currentRefinementId)
          newPreviousRefinements[currentRefinementIndex] = updatedRefinement
          return newPreviousRefinements
        })
      }
    },
    [currentRefinementId, fileSyncerStarted, getFileSyncerV2, previousRefinements, setCurrentRefinement],
  )

  const updateIterationsFromServer = useCallback(async () => {
    // Fetch the iterations from DB first so that metadata can be merged with commits from git
    const iterationsFetchedFromDb = await fetchIterationsFromDb()
    iterationsInDbRef.current = iterationsFetchedFromDb
    const {iterations: iterationsFetchedFromGit, currentRefinement} = await fetchIterationHistoryFromGitV2()
    setPreviousRefinements(iterationsFetchedFromGit)
    setCurrentRefinementSha(currentRefinement?.sha)
    forceContentRefresh()
    forceFileTreeRefresh()

    async function fetchIterationsFromDb() {
      const response = await verifiedFetchJSON(`/copilot/spark/workbench/${workbench.id}/iterations`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      })
      const {iterations} = await response.json()
      return iterations
    }
  }, [fetchIterationHistoryFromGitV2, forceContentRefresh, forceFileTreeRefresh, workbench.id])

  const {previousRefinementSha} = useMemo(() => {
    const currIndex = previousRefinements.findIndex(ref => ref.id === currentRefinementId)
    const prevRefinement = previousRefinements[currIndex - 1]
    return {
      currentRefinementIndex: currIndex,
      previousRefinementSha: prevRefinement?.sha || null,
    }
  }, [currentRefinementId, previousRefinements])

  const isInitialIteration = useMemo(() => {
    return (
      !previousRefinements ||
      !previousRefinements.length ||
      !previousRefinements.some(x => x.iteration_type === 'ai' && x.sha)
    )
  }, [previousRefinements])

  const value = useMemo(
    () => ({
      setPreviousRefinements,
      setCurrentRefinement,
      previousRefinements,
      currentRefinementId,
      isNavigatingHistory,
      setIsNavigatingHistory,
      updateUserEditStatus,
      updateIterationsFromServer,
      currentRefinementSha,
      previousRefinementSha,
      isInitialIteration,
      refreshGitHistory,
      notifyRehydrateCompleted,
      gitHistoryRestored,
    }),
    [
      currentRefinementId,
      currentRefinementSha,
      isNavigatingHistory,
      isInitialIteration,
      previousRefinementSha,
      previousRefinements,
      setCurrentRefinement,
      updateIterationsFromServer,
      updateUserEditStatus,
      refreshGitHistory,
      notifyRehydrateCompleted,
      gitHistoryRestored,
    ],
  )
  return <IterationHistoryContext value={value}>{children}</IterationHistoryContext>
}

export const IterationHistoryContext = createContext<IterationHistoryContext | undefined>(undefined)

export function useIterationHistory() {
  const context = use(IterationHistoryContext)
  if (!context) {
    throw new Error('useIterationHistory must be used within an IterationHistoryProvider')
  }
  return context
}
